sed -i '/export default function Home() {/a \  const [stats, setStats] = useState({ projects: "3+", activeVolunteers: "0+", eventsHosted: "0+", volunteerApps: "0+" });\n  useEffect(() => {\n    async function fetchStats() {\n      try {\n        const projSnap = await getCountFromServer(collection(db, "projects"));\n        \n        const volunteersRef = collection(db, "volunteers");\n        const pendingQ = query(volunteersRef, where("status", "==", "pending"));\n        const approvedQ = query(volunteersRef, where("status", "==", "approved"));\n        \n        const [pendingSnap, approvedSnap] = await Promise.all([\n          getCountFromServer(pendingQ),\n          getCountFromServer(approvedQ)\n        ]);\n        \n        setStats({\n          projects: projSnap.data().count + "+",\n          activeVolunteers: approvedSnap.data().count + "+",\n          eventsHosted: "0+",\n          volunteerApps: pendingSnap.data().count + "+"\n        });\n      } catch (error) {\n        console.error("Error fetching stats:", error);\n      }\n    }\n    fetchStats();\n  }, []);' src/pages/Home.tsx
